import { readFileSync, writeFileSync } from 'node:fs';
import { DynamicScheme, Hct, MaterialDynamicColors, TonalPalette, Variant, hexFromArgb } from '@material/material-color-utilities';

/** One Material 3 token source for the web (CSS custom properties) and Android (Compose color schemes).
 * No network and no fonts are fetched. `--check` fails when generated files differ from design/tokens.json. */
type Hue = { hue: number; chroma: number };
type Tokens = { palettes: Record<'primary' | 'secondary' | 'tertiary' | 'neutral' | 'neutralVariant', Hue>; semantic: Record<string, Hue & { containerChroma: number }>; shape: Record<string, number>; typeface: { brand: string; plain: string; mono: string } };
const tokens = JSON.parse(readFileSync(new URL('../design/tokens.json', import.meta.url), 'utf8')) as Tokens;
const check = process.argv.includes('--check');
type Role = { getArgb(scheme: never): number };
const dynamic = MaterialDynamicColors as unknown as Record<string, Role>;
const roles = ['primary', 'onPrimary', 'primaryContainer', 'onPrimaryContainer', 'inversePrimary', 'secondary', 'onSecondary', 'secondaryContainer', 'onSecondaryContainer',
  'tertiary', 'onTertiary', 'tertiaryContainer', 'onTertiaryContainer', 'error', 'onError', 'errorContainer', 'onErrorContainer', 'background', 'onBackground',
  'surface', 'onSurface', 'surfaceVariant', 'onSurfaceVariant', 'surfaceDim', 'surfaceBright', 'surfaceContainerLowest', 'surfaceContainerLow', 'surfaceContainer',
  'surfaceContainerHigh', 'surfaceContainerHighest', 'surfaceTint', 'inverseSurface', 'inverseOnSurface', 'outline', 'outlineVariant', 'shadow', 'scrim'] as const;
const kebab = (value: string) => value.replace(/[A-Z]/g, letter => '-' + letter.toLowerCase());
const hex = (argb: number) => hexFromArgb(argb).toUpperCase();
const palette_ = (value: Hue) => TonalPalette.fromHueAndChroma(value.hue, value.chroma);
function scheme(dark: boolean) {
  const { primary, secondary, tertiary, neutral, neutralVariant } = tokens.palettes;
  return new DynamicScheme({ sourceColorHct: Hct.from(primary.hue, primary.chroma, 40), variant: Variant.TONAL_SPOT, contrastLevel: 0, isDark: dark,
    primaryPalette: palette_(primary), secondaryPalette: palette_(secondary), tertiaryPalette: palette_(tertiary), neutralPalette: palette_(neutral), neutralVariantPalette: palette_(neutralVariant) });
}
function palette(dark: boolean) {
  const value = scheme(dark), colors: Record<string, string> = Object.fromEntries(roles.map(role => [role, hex(dynamic[role].getArgb(value as never))]));
  // Semantic roles are not part of Material 3. Foreground tones are vivid, containers are calm so status never shouts.
  for (const [name, token] of Object.entries(tokens.semantic)) {
    const main = TonalPalette.fromHueAndChroma(token.hue, token.chroma), container = TonalPalette.fromHueAndChroma(token.hue, token.containerChroma), cap = name[0].toUpperCase() + name.slice(1);
    colors[name] = hex(main.tone(dark ? 80 : 40)); colors[`on${cap}`] = hex(main.tone(dark ? 20 : 100));
    colors[`${name}Container`] = hex(container.tone(dark ? 30 : 90)); colors[`on${cap}Container`] = hex(container.tone(dark ? 90 : 10));
  }
  return colors;
}
const light = palette(false), dark = palette(true);
const semanticKeys = Object.keys(light).filter(key => !(roles as readonly string[]).includes(key));
const cssBlock = (colors: Record<string, string>) => Object.entries(colors).map(([key, value]) => `  --md-sys-color-${kebab(key)}: ${value};`).join('\n');
const css = `/* GENERATED by scripts/generate-design-tokens.ts from design/tokens.json. Do not edit. */
:root {
  color-scheme: light dark;
${cssBlock(light)}
  --md-ref-typeface-brand: ${tokens.typeface.brand};
  --md-ref-typeface-plain: ${tokens.typeface.plain};
  --ops-typeface-mono: ${tokens.typeface.mono};
${Object.entries(tokens.shape).map(([key, value]) => `  --md-sys-shape-corner-${kebab(key)}: ${value}px;`).join('\n')}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
${cssBlock(dark).replace(/^/gm, '  ')}
  }
}
:root[data-theme='dark'] {
${cssBlock(dark)}
}
`;
const kotlinColor = (value: string) => `Color(0xFF${value.slice(1)})`;
// ColorScheme has no shadow role; Compose draws shadows in black.
const schemeRoles = roles.filter(role => role !== 'shadow');
const kotlinScheme = (name: string, factory: string, colors: Record<string, string>) => `val ${name} = ${factory}(\n${schemeRoles.map(role => `    ${role} = ${kotlinColor(colors[role])},`).join('\n')}\n)`;
const kotlin = `// GENERATED by scripts/generate-design-tokens.ts from design/tokens.json. Do not edit.
package app.mobileops.agent.app

import androidx.compose.material3.ColorScheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.ui.graphics.Color

${kotlinScheme('OpsLightColors', 'lightColorScheme', light)}

${kotlinScheme('OpsDarkColors', 'darkColorScheme', dark)}

/** Roles that Material 3 does not define. They share the web token names (--md-sys-color-success and so on). */
class OpsSemanticColors(${semanticKeys.map(key => `val ${key}: Color`).join(', ')})
val OpsLightSemantic = OpsSemanticColors(${semanticKeys.map(key => kotlinColor(light[key])).join(', ')})
val OpsDarkSemantic = OpsSemanticColors(${semanticKeys.map(key => kotlinColor(dark[key])).join(', ')})
fun opsSemantic(dark: Boolean) = if (dark) OpsDarkSemantic else OpsLightSemantic
fun opsColorScheme(dark: Boolean): ColorScheme = if (dark) OpsDarkColors else OpsLightColors
`;
const outputs: [URL, string][] = [[new URL('../apps/web/src/theme.generated.css', import.meta.url), css], [new URL('../apps/android/app/src/main/java/app/mobileops/agent/app/Theme.kt', import.meta.url), kotlin]];
for (const [file, content] of outputs) {
  if (check) { let current = ''; try { current = readFileSync(file, 'utf8'); } catch { /* A missing file is a difference. */ } if (current !== content) throw Error(`Generated design tokens differ from design/tokens.json: ${file.pathname.split('/').at(-1)}`); }
  else writeFileSync(file, content);
}
console.log(check ? 'Design tokens match design/tokens.json.' : `Generated design tokens: primary ${light.primary} (light), ${dark.primary} (dark), ${semanticKeys.length} semantic roles.`);
